{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE gift_card_summary AS ( WITH gift_card_credit AS ( SELECT wt.points_batch_id, TO_VARCHAR(wt.shopify_user_id) AS received_by, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', TRY_TO_TIMESTAMP(wt.created_at)) AS credited_on, TRY_TO_NUMBER(wt.amount) AS amount_credited, TRY_TO_NUMBER(wt.shopify_order_id) AS issued_order_id, wt.bill_no FROM s3_bucket_wallet_transaction_db wt WHERE wt.type = \'GIFT_CARD_CREDIT\' AND wt.points_batch_id IS NOT NULL ), issued_online AS ( SELECT order_id, order_name AS issued_order_name, TO_VARCHAR(customer_id) AS issued_by, MAX(order_timestamp) AS issued_on, SUM(gross_sales) AS issued_gross_sales, SUM(discount) AS issued_discount, NULL as issued_branch_code, \'Online\' AS purchase_channel FROM fact_items_snitch WHERE tags = \'Gift_Card_Purchase\' AND customer_id NOT IN (\'9109658566818\', \'8631470391458\', \'8084897497250\', \'7805163503778\', \'8187980546210\', \'8222759518370\', \'7305859694754\') GROUP BY order_id, order_name, customer_id ), issued_offline AS ( SELECT NULL AS order_id, TRIM(ros.bill_no) AS issued_order_name, TRIM(ros.shopify_user_id) AS issued_by, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN COALESCE( TRY_TO_TIMESTAMP(ros.vouch_time), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH:MI AM\') ) ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS issued_on, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_gift_card_value),\'[^0-9\.-]\',\'\')) AS issued_gross_sales, 0::NUMBER AS issued_discount, store_code as issued_branch_code, \'Offline\' AS purchase_channel FROM snitch_db.maplemonk.retail_order_summary ros WHERE TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_gift_card_value),\'[^0-9\.-]\',\'\')) > 0 AND shopify_user_id <> \'8059258175650\' ), issued_order_details AS ( SELECT * FROM issued_online UNION ALL SELECT * FROM issued_offline ), gift_card_debit AS ( SELECT wt.points_batch_id, TO_VARCHAR(wt.shopify_user_id) AS redeemed_by, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', TRY_TO_TIMESTAMP(wt.created_at)) AS redeemed_on, ABS(TRY_TO_NUMBER(wt.amount)) AS amount_redeemed, CASE WHEN wt.reason = \'Purchase : Store\' THEN TRIM(wt.bill_no) ELSE TRIM(SPLIT_PART(wt.shopify_order_number, \'.\', 1)) END AS redeemed_order_name, CASE WHEN wt.reason = \'Purchase : Online\' THEN \'Online\' WHEN wt.reason = \'Purchase : Store\' THEN \'Offline\' ELSE NULL END AS redemption_channel_event FROM s3_bucket_wallet_transaction_db wt WHERE wt.type = \'GIFT_CARD_DEBIT\' AND wt.reason IN (\'Purchase : Online\', \'Purchase : Store\') AND wt.points_batch_id IS NOT NULL ), redeemed_online AS ( SELECT order_name, MAX(order_timestamp) AS redeemed_order_ts, SUM(gross_sales) AS redeemed_gross_sales, SUM(discount) AS redeemed_discount, NULL as branch_code, \'Online\' AS channel FROM fact_items_snitch WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' GROUP BY order_name ), redeemed_offline AS ( SELECT TRIM(ros.bill_no) AS order_name, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS redeemed_order_ts, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9\.-]\',\'\')) AS redeemed_gross_sales, ABS(( TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_gross_value),\'[^0-9\.-]\',\'\')) - TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.-]\',\'\')) )) AS redeemed_discount, store_code as branch_code, \'Offline\' AS channel FROM snitch_db.maplemonk.retail_order_summary ros ), redeemed_order_details AS ( SELECT * FROM redeemed_online UNION ALL SELECT * FROM redeemed_offline ), gift_card_redemption_summary AS ( SELECT d.points_batch_id, MAX(d.redeemed_by) AS redeemed_by, MAX(d.redeemed_on) AS last_redeemed_on, LISTAGG(d.redeemed_order_name, \', \') WITHIN GROUP (ORDER BY d.redeemed_on) AS all_redeemed_orders, SUM(d.amount_redeemed) AS total_redeemed, SUM(r.redeemed_gross_sales) AS redeemed_gross_sales, SUM(r.redeemed_discount) AS redeemed_discount, MAX(branch_code) AS redeemed_branch_code, CASE WHEN MIN(d.redemption_channel_event) = MAX(d.redemption_channel_event) THEN MIN(d.redemption_channel_event) ELSE \'Mixed\' END AS redemption_channel FROM gift_card_debit d LEFT JOIN redeemed_order_details r ON d.redeemed_order_name = r.order_name GROUP BY d.points_batch_id ), user_orders_online AS ( SELECT TO_VARCHAR(customer_id) AS shopify_user_id, MIN(order_timestamp) AS first_order_date FROM fact_items_snitch GROUP BY customer_id ), user_orders_offline AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, MIN( CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END ) AS first_order_date FROM snitch_db.maplemonk.retail_order_summary GROUP BY TRIM(shopify_user_id) ), user_orders_summary AS ( SELECT shopify_user_id, MIN(first_order_date) AS first_order_date FROM ( SELECT * FROM user_orders_online UNION ALL SELECT * FROM user_orders_offline ) GROUP BY shopify_user_id ), snitchx_membership AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(membership_enrolled_date), \':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) AS snitchx_enrolled_at FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), store_map AS ( SELECT CAST(STORE_CODE AS STRING) AS store_code, STORE_NAME AS store_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING WHERE STORE_NAME NOT ILIKE \'%NIL%\' AND STORE_NAME NOT ILIKE \'%SNITCH-WH%\' ) SELECT c.points_batch_id, od.issued_by, od.issued_order_name, od.issued_on, od.issued_gross_sales, od.issued_discount, od.purchase_channel AS purchase_channel, od.issued_branch_code, sm_i.store_name as issued_store_name, c.received_by, c.credited_on, c.amount_credited, grs.redeemed_by, grs.last_redeemed_on AS redeemed_on, grs.total_redeemed AS amount_redeemed, grs.all_redeemed_orders AS redeemed_order_name, grs.redeemed_gross_sales, grs.redeemed_discount, grs.redemption_channel AS redemption_channel, grs.redeemed_branch_code, sm_r.store_name as redeemed_store_name, CASE WHEN grs.total_redeemed IS NULL THEN \'Unredeemed\' WHEN grs.total_redeemed = c.amount_credited THEN \'Fully Redeemed\' WHEN grs.total_redeemed < c.amount_credited THEN \'Partially Redeemed\' ELSE \'Check\' END AS redemption_status, CASE WHEN grs.total_redeemed = c.amount_credited THEN DATEDIFF(DAY, od.issued_on, grs.last_redeemed_on) ELSE NULL END AS tat_purchase_to_redeem, CASE WHEN c.credited_on IS NULL THEN NULL ELSE DATEDIFF(DAY, od.issued_on, c.credited_on) END AS tat_purchase_to_credit, CASE WHEN grs.total_redeemed = c.amount_credited THEN DATEDIFF(DAY, c.credited_on, grs.last_redeemed_on) ELSE NULL END AS tat_credit_to_redeem, CASE WHEN credited_on IS NOT NULL THEN NULL WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 8 THEN \'0–7 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 16 THEN \'8–15 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 30 THEN \'16–30 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 60 THEN \'31–60 days\' ELSE \'> 60 days\' END AS not_credited_ageing_bucket, CASE WHEN grs.total_redeemed >= c.amount_credited THEN NULL WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 8 THEN \'0–7 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 16 THEN \'8–15 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 30 THEN \'16–30 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 60 THEN \'31–60 days\' ELSE \'> 60 days\' END AS unredeemed_ageing_bucket, CASE WHEN grs.total_redeemed IS NULL THEN \'Not Redeemed\' WHEN od.issued_by = grs.redeemed_by THEN \'Yes\' ELSE \'No\' END AS redeemed_by_same_user, CASE WHEN sm_issuer.shopify_user_id IS NOT NULL AND od.issued_on >= sm_issuer.snitchx_enrolled_at THEN \'X\' WHEN uos_issuer.first_order_date IS NULL THEN \'New\' WHEN uos_issuer.first_order_date >= od.issued_on THEN \'New\' ELSE \'Repeat\' END AS issuer_type, CASE WHEN grs.total_redeemed IS NULL THEN NULL WHEN sm_redeemer.shopify_user_id IS NOT NULL AND grs.last_redeemed_on >= sm_redeemer.snitchx_enrolled_at THEN \'X\' WHEN uos_redeemer.first_order_date IS NULL THEN \'New\' WHEN uos_redeemer.first_order_date >= grs.last_redeemed_on THEN \'New\' ELSE \'Repeat\' END AS redeemer_type FROM issued_order_details od LEFT JOIN gift_card_credit c ON od.order_id = c.issued_order_id LEFT JOIN gift_card_redemption_summary grs ON c.points_batch_id = grs.points_batch_id LEFT JOIN user_orders_summary uos_issuer ON od.issued_by = uos_issuer.shopify_user_id LEFT JOIN user_orders_summary uos_redeemer ON grs.redeemed_by = uos_redeemer.shopify_user_id LEFT JOIN snitchx_membership sm_issuer ON od.issued_by = sm_issuer.shopify_user_id LEFT JOIN snitchx_membership sm_redeemer ON grs.redeemed_by = sm_redeemer.shopify_user_id LEFT JOIN store_map sm_i ON od.issued_branch_code = sm_i.store_code LEFT JOIN store_map sm_r ON grs.redeemed_branch_code = sm_r.store_code WHERE od.issued_on > \'2025-06-10\' ORDER BY od.issued_on DESC ); CREATE OR REPLACE TABLE qwikcilver_gift_cards AS ( SELECT NULLIF(TRIM(transaction_type), \'\') AS transaction_type, NULLIF(TRIM(transaction_mode), \'\') AS transaction_mode, REGEXP_REPLACE(TRIM(card_number), \'^\'\'\', \'\') AS card_number, COALESCE( TRY_TO_DATE(TRIM(transaction_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(transaction_date)) ) AS transaction_date, TRY_TO_TIME(TRIM(transaction_time)) AS transaction_time, COALESCE( TRY_TO_DATE(TRIM(transaction_postdate), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(transaction_postdate)) ) AS transaction_post_date, COALESCE( TRY_TO_DATE(TRIM(expiry_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(expiry_date)) ) AS expiry_date, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(amount), \'[^0-9\.\-]\', \'\')) AS amount, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(bill_amount), \'[^0-9\.\-]\', \'\')) AS bill_amount, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(currency_converted_amount), \'[^0-9\.\-]\', \'\')) AS currency_converted_amount, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(adjustment_amount), \'[^0-9\.\-]\', \'\')) AS adjustment_amount, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(card_balance), \'[^0-9\.\-]\', \'\')) AS card_balance, TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(pre_transaction_card_balance), \'[^0-9\.\-]\', \'\')) AS pre_transaction_card_balance, NULLIF(TRIM(program_group), \'\') AS program_group, NULLIF(TRIM(issuer), \'\') AS issuer, NULLIF(TRIM(merchant), \'\') AS merchant, NULLIF(TRIM(corporate_name), \'\') AS corporate_name, NULLIF(TRIM(outlet), \'\') AS outlet, NULLIF(TRIM(descriptive_outlet_name), \'\') AS descriptive_outlet_name, NULLIF(TRIM(region), \'\') AS region, NULLIF(TRIM(pos_name), \'\') AS pos_name, NULLIF(TRIM(initiated_by), \'\') AS initiated_by, NULLIF(TRIM(card_entry_mode), \'\') AS card_entry_mode, NULLIF(TRIM(reference_number), \'\') AS reference_number, NULLIF(TRIM(invoice_number), \'\') AS invoice_number, NULLIF(TRIM(approval_code), \'\') AS approval_code, NULLIF(TRIM(batch_number), \'\') AS batch_number, NULLIF(TRIM(booklet_number), \'\') AS booklet_number, NULLIF(REGEXP_REPLACE(TRIM(original_cardnumber_before_reissue), \'^\'\'\', \'\'), \'\') AS original_cardnumber_before_reissue, NULLIF(TRIM(universal_product_code), \'\') AS universal_product_code, NULLIF(TRIM(response_message), \'\') AS response_message, NULLIF(TRIM(notes), \'\') AS notes FROM qwikcilver_gift_card_transaction );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            